import{_ as d,o as r,c as e,a2 as a}from"./chunks/framework.BXzK3EA4.js";const _=JSON.parse('{"title":"用户身份与权限","description":"","frontmatter":{"title":"用户身份与权限"},"headers":[],"relativePath":"beginners-guide/account/user-roles.md","filePath":"beginners-guide/account/user-roles.md","lastUpdated":1793696072000}'),o={name:"beginners-guide/account/user-roles.md"};function s(h,t,n,i,l,b){return r(),e("div",null,[...t[0]||(t[0]=[a('<p>本文介绍您在访问 RakSmart 资源前，需了解的通用用户身份分类、各身份核心特性、适用场景及对应的权限范围，帮助您更合理地进行账户权限管理与资源访问控制。关于如何配置用户身份权限可参考<a href="./user-permissions.html">为普通用户授权</a>。</p><hr><h3 id="用户身份类型" tabindex="-1">用户身份类型 <a class="header-anchor" href="#用户身份类型" aria-label="Permalink to &quot;用户身份类型&quot;">​</a></h3><p>RakSmart 将用户身份分为两种类型：所有者权限用户和普通权限用户。</p><table tabindex="0"><thead><tr><th>维度</th><th>所有者权限用户</th><th>普通权限用户</th></tr></thead><tbody><tr><td>角色定位</td><td>账户核心主体，是最高权限 + 责任归属者。</td><td>所有者创建的附属角色，仅获部分授权的协作账号。</td></tr><tr><td>权限范围</td><td>- 默认拥有账户所有功能操作权；<br>- 可创建/修改/回收其他用户权限。</td><td>- 仅拥有所有者分配的部分权限；<br>- 无超授权范围的操作权限。</td></tr><tr><td>账户属性</td><td>- 独立账户所有权；<br>- 承担账户法律、财务责任。</td><td>- 无独立账户所有权，依附主账户；<br>- 权限完全由所有者管控。</td></tr><tr><td>适用场景</td><td>- 企业 IT 管理员/个人站长（统筹管理）；<br>- 单人独立使用账户。</td><td>- 企业分工（运维 / 财务等角色）；<br>- 外包/临时协作（授权指定资源）。</td></tr><tr><td>注意事项</td><td>- 严格保密账号信息；<br>- 避免共享账号，建议创建普通用户协作。</td><td>- 需联系所有者修改账号信息；<br>- 遵循 “最小必要原则” 分配权限，避免过度授权。</td></tr></tbody></table><hr><h3 id="用户权限类型" tabindex="-1">用户权限类型 <a class="header-anchor" href="#用户权限类型" aria-label="Permalink to &quot;用户权限类型&quot;">​</a></h3><p>权限是指不同用户身份对具体资源的访问能力，即在某种条件下允许或拒绝对某些资源执行某些操作。</p><table tabindex="0"><thead><tr><th>实体用户身份</th><th>权限标识</th><th>默认权限</th><th>是否需要授权</th><th>授权说明</th></tr></thead><tbody><tr><td>所有者权限用户</td><td>带“所有者标签”。</td><td>默认拥有账户的“完全管理权限”，可操作所有功能、管理用户。</td><td>否</td><td>账号默认拥有完全控制权，无需额外授权；所有资源的创建、删除及核心配置变更，均需通过所有者身份触发。</td></tr><tr><td>普通权限用户</td><td>无“所有者”标签。</td><td>仅拥有账户所有者分配的权限项。</td><td>是</td><td>账户所有者通过“管理权限”功能分配/修改/回收相关权限。</td></tr></tbody></table>',9)])])}const u=d(o,[["render",s]]);export{_ as __pageData,u as default};
